#!/usr/bin/env bash
#
# Run the built client against a local OreStudio environment.
#
# The environment's own .env file is handed to the client, which reads the
# NATS URL, subject prefix, wire format and client certificates from it. That
# keeps Hedgr pointed at the same broker as the rest of the deployment with no
# settings to retype. Any argument given here still overrides the file.
#
# The environment file is generated by `compass env create`, one per checkout
# (e.g. ores_dev_brave_hopper/.env). Point ORES_ENV_FILE elsewhere to use a
# different environment.
#
# Examples:
#   build/scripts/run.sh --log-enabled --log-level info
#   build/scripts/run.sh --nats-subject-prefix ores.dev.local1
#
set -euo pipefail

repo_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)

ores_source_dir=${ORES_SOURCE_DIR:-/home/marco/Development/OreStudio/ores_dev_brave_hopper}
env_file=${ORES_ENV_FILE:-${ores_source_dir}/.env}
binary=${repo_dir}/build/output/linux-clang-release/publish/bin/hedgr.imgui

if [ ! -x "${binary}" ]; then
    echo "error: ${binary} not found; run build/scripts/build.sh first" >&2
    exit 1
fi
if [ ! -f "${env_file}" ]; then
    echo "error: environment file not found: ${env_file}" >&2
    exit 1
fi

# Read the deployment's settings into this shell and let the client pick them
# up through the standard environment mapping, rather than teaching the client
# to parse a file.
set +u
set -a
# shellcheck disable=SC1090
. "${env_file}"
set +a
set -u

# The shared ORES_NATS_* domain covers the URL, subject prefix and wire format.
# The TLS trio is deliberately excluded from it, so restate those under this
# client's own ORES_<APP>_ prefix, which is the form its mapper expects.
if [ -n "${ORES_NATS_TLS_CA:-}" ]; then
    export ORES_HEDGR_NATS_TLS_CA="${ORES_NATS_TLS_CA}"
    export ORES_HEDGR_NATS_TLS_CERT="${ORES_NATS_TLS_CERT}"
    export ORES_HEDGR_NATS_TLS_KEY="${ORES_NATS_TLS_KEY}"
fi

exec "${binary}" "$@"
